INSERT INTO emoji (id, name, url, tags, description, category, hot_score, source, create_time) VALUES
  (11, '滑稽大佬00005-菜刀-给你看看爸爸的', '/static/emojis/real/bqb-03.gif', '滑稽大佬00005-菜刀-给你看看爸爸的,滑稽大佬', '贱兮兮地举着菜刀晃悠，一脸"给你看看爸爸的厉害"，装逼挑衅、狐假虎威，怼人嘲讽专用', 'funny', 900, 'LOCAL', NOW()),
